\label{def:uas}
A randomized algorithm $\mathcal{A}:\ensuremath{\mathcal{X}}^n\mapsto\mathcal{W}\times\Theta$ satisfies $\Delta$-uniform argument stability (UAS) if for any pair of adjacent datasets $S,S'\in\ensuremath{\mathcal{X}}^n$ it holds that  
$\underset{\mathcal{A}}{\mathbb{E}}\left[ \left\|\mathcal{A}(S)-\mathcal{A}(S')\right\| \right] \leq \Delta$.

\label{lem:sc-ssp-stability}
Let $\psi:\mathcal{W}\times\Theta\mapsto\mathbb{R}$ be $\mu$-strongly-convex/strongly-concave w.r.t. $\|\cdot\|_w$ and $\|\cdot\|_\theta$. Then the algorithm which returns the saddle point of 
$(w,\theta) \mapsto \frac{1}{n}\sum_{z\in S} f(w,\theta;z) + \psi(w,\theta)$ is $(\frac{2L}{\mu n})$-UAS.

\label{asm:weak-alg}
Given a dataset $S'\in\ensuremath{\mathcal{X}}^{n'}$, loss function $f'$, and an initial point $[w',\theta'],$ we say that $\mathcal{A}_{\mathsf{sub}}$ satisfies $\hat{\alpha}$-relative accuracy w.r.t.~the empirical saddle point $[w_{S'}^*, \theta_{S'}^*]$ of $F'_{S'}(w,\theta)=\frac{1}{n'}\sum_{x\in {S'}}f'(w,\theta;x)$ 
if, $\forall \hat{D}>0$, whenever $\underset{}{\mathbb{E}}\left[ \left\|[w',\theta'] - [w^*_{S'},\theta^*_{S'}]\right\| \right] \leq \hat{D}$, the output $[\bar{w},\bar{\theta}]$ of $\mathcal{A}_{\mathsf{sub}}$ satisfies $\underset{}{\mathbb{E}}\left[ F'_{S'}(\bar{w},\theta^*_{S'})- F'_{S'}(w^*_{S'},\bar{\theta}) \right] \leq \hat{D}\hat{\alpha}$.

\label{lem:ra-stab-gen}
Let $f:\ensuremath{\mathcal{Z}}\times\ensuremath{\mathcal{X}}\mapsto \mathbb{R}$ be $L$-Lipschitz. Let $[w^*,\theta^*]\in\ensuremath{\mathcal{Z}}$ be the population saddle point. For any $x\in\ensuremath{\mathcal{X}}$ define $h([w,\theta];x)=f(w,\theta^*;x) - f(w^*,\theta;x)$. For $S\sim \mathcal{D}^n$, let $H_S(z) = \frac{1}{n}\sum_{x\in S} h(z;x)$ and $H_\mathcal{D}(z) = \underset{x\sim\mathcal{D}}{\mathbb{E}}\left[ h(z;x) \right]$. Then for any $\Delta$-UAS algorithm, $\mathcal{A}$, one has
$\underset{S,A}{\mathbb{E}}\left[ H_\mathcal{D}(\mathcal{A}(S))-H_S(\mathcal{A}(S)) \right] \leq 2\Delta L$.

\label{thm:recursive-regularization-vi}
Let $\mathcal{A}_{\mathsf{sub}}$ satisfy $\hat{\alpha}$-relative stationarity for any 
$(5L)$-bounded monotone operator and dataset of size $n'=\frac{n}{\log(n)}$. Let $\rho$ satisfy Assumption \ref{assm:operator}.
Then 
Algorithm~\ref{alg:recursive-regularization}, 
run with $\mathcal{A}_{\mathsf{sub}}$ as a subroutine and $\lambda=\frac{48}{B}\left({\hat{\alpha}\kappa^3 + \frac{(\betaB+L)\kappa^2}{\sqrt{n'}}}\right)$,  
satisfies 
\begin{align*}
    \operatorname{VI-Gap}(\mathcal{R}_{\text{SVI}}) = O\Big(\log(n)B\hat{\alpha}\kappa^3 + \frac{\log^{3/2}(n)B(\betaB+L)\kappa^2}{\sqrt{n}}\Big).
\end{align*}

\label{def:rel-acc}
Given a dataset $S'\in\ensuremath{\mathcal{X}}^{n'}$, operator $g'$, and an initial point $z'$, we say that $\mathcal{A}_{\mathsf{sub}}$ satisfies $\hat{\alpha}$-relative stationarity w.r.t. to the empirical equilibrium $z^*_{S'}$ of $G_{S'}(z)=\frac{1}{n'}\sum_{x\in S'}g'(z;x)$,  
if, $\forall \hat{D}>0$, whenever $\underset{}{\mathbb{E}}\left[ \left\|z' - z^*_{S'}\right\| \right] \leq \hat{D}$, the output $\bar{z}$ of $\mathcal{A}_{\mathsf{sub}}$ satisfies          \linebreak           $\underset{}{\mathbb{E}}\left[ \left\langle G(\bar z),\bar z-z^*_{S'} \right\rangle \right] \leq \hat{D}\hat{\alpha}$.

There exists an Algorithm, $\mathcal{R}$, which is $(\epsilon,\delta)$-DP, has gradient evaluations bounded by          \linebreak     $O\big(\min\big\{\frac{\sqrt{\kappa}n^2\epsilon^{1.5}}{\log(n)\sqrt{d\log(1/\delta)\tilde{\kappa}}}, \frac{\sqrt{\kappa}n^{3/2}}{\sqrt{\log(n)}}\big\}\big)$,  
and satisfies (up to $\log(n)$ factors)
\begin{align} \label{eq:main-svi-result}
    \operatorname{VI-Gap}(\mathcal{R}) = \tilde{O}\Big(\kappa^{3.5}BL\big(\frac{\sqrt{d\log(1/\delta)\tilde{\kappa}}}{n\epsilon} + \frac{1}{\sqrt{n}}\big)\Big).
\end{align}
where $\kappa = \frac{1}{\max\left\{{p,1+\frac{1}{\log(d)}}\right\}-1}$ is at most $\log(d)$ and $\tilde{\kappa} = 1+\mathbf{1}\left\{{p<2}\right\}\cdot\log(d)$.

\label{thm:generalized-rr-convergence}
Let $\lambda \geq \frac{48L\kappa^{3/2}}{B\sqrt{n'}}$
and $\mathcal{A}_{\mathsf{sub}}$ be such that for all $t\in [T]$ it holds that                            $\underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z^*_{S,t}\right\|^2 \right] \leq \frac{B^2}{12\cdot2^{2t}\kappa^{3/2}}$.
Then Recursive Regularization satisfies
\begin{align*}
    \operatorname{Gap_{\mathsf{SP}}}(\mathcal{R}_{\text{SSP}}) = O\Big(\log(n)B^2\lambda\Big).
\end{align*}

\label{fact:rel-acc-bounds-distance}
Let $F:\ensuremath{\mathcal{Z}}\mapsto\mathbb{R}^d$ be a $\gamma$-SC/SC function and let $[w^*,\theta^*]$ be the saddle point. Then 
$\|[w,\theta]-[w^*,\theta^*]\|^2 \leq \frac{2\left({F(w,\theta^*)-F(\theta^*,w)}\right)}{\lambda}$.

\label{lem:phase-distance-bound}
Assume the conditions of Theorem \ref{thm:generalized-rr-convergence} hold. Then for every $t\in[T]$, the following holds
\begin{enumerate}[label=\textbf{P.\arabic*}]
    \item $\underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z_{t}^*\right\| \right]^2 \leq \underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z_{t}^*\right\|^2 \right] \leq \frac{B^2}{2^{2t}\kappa}$; and, \label{prop:p1}
    \item $B_t^2 := \underset{}{\mathbb{E}}\left[ \left\|z_{t}^* - z^*_{t-1}\right\| \right]^2 \leq \underset{}{\mathbb{E}}\left[ \left\|z_{t}^* - z^*_{t-1}]\right\|^2 \right] \leq \frac{B^2}{2^{2(t-1)}}$. \label{prop:p2}
\end{enumerate}

\label{lem:mirror-prox-bound}
Let $\psi:\ensuremath{\mathcal{Z}}\mapsto\mathbb{R}$ be any non-negative function which is $1$-strongly convex w.r.t. $\|\cdot\|$.
Assume $\forall t\in[T]$ that $\underset{}{\mathbb{E}}\left[ \ensuremath{\mathcal{O}}(z_t) \right]=G(z_t)$ and $\underset{}{\mathbb{E}}\left[ \|\ensuremath{\mathcal{O}}(z_t) - G(z_t)\|_*^2 \right] \leq \tau^2$. Then for for any $z\in\ensuremath{\mathcal{Z}}$ Algorithm \ref{alg:mirror-prox} satisfies
\begin{align*}
    \underset{}{\mathbb{E}}\left[ \frac{1}{T}\sum_{t=1}^T\left\langle G(z_t),z_t-z \right\rangle \right] = O\left({\frac{\underset{}{\mathbb{E}}\left[ \psi(z) \right]}{T\eta} + \frac{7\eta}{2}(L^2 + 2\tau^2)}\right).
\end{align*}

\label{thm:noisy-mirror-prox}
Let $[w_0,\theta_0],[w,\theta]$ satisfy $\underset{}{\mathbb{E}}\left[ \|[w_0,\theta_0]-[w,\theta]\| \right] \leq \hat{D}$. Let $g:\mathcal{W}\times\Theta \times \ensuremath{\mathcal{X}} \mapsto \mathcal{B}^{d_w}_{\|\cdot\|_{\bar{p}}}(B_w L_w)\times\mathcal{B}^{d_\theta}_{\|\cdot\|_{\bar{q}}}(B_\theta L_\theta)$ be a monotone operator and $G_S(w,\theta)=\frac{1}{n}\sum_{x\in S} g([w,\theta];x)$.
There exists an implementation of 
$\ensuremath{\mathcal{O}}$ such that Algorithm \ref{alg:mirror-prox} is $(\epsilon,\delta)$-DP and the following holds
\begin{align*}
    &\underset{}{\mathbb{E}}\left[ \left\langle G_S([w_{t^*},\theta_{t^*}]),[w_{t^*},\theta_{t^*}]-[w,\theta] \right\rangle \right] = \underset{}{\mathbb{E}}\left[ \frac{1}{T}\sum_{t=1}^T\left\langle G_S([w_t,\theta_t]),[w_t,\theta_t]-[w,\theta] \right\rangle \right] \\
    &\quad = O\left({\hat{D}\sqrt{B_w^2L_w^2+B_\theta^2L_\theta^2}\left({\frac{\sqrt{\kappa}\sqrt{d\log(1/\delta)\tilde{\kappa}}}{n\epsilon} + \frac{\sqrt{\kappa}}{\sqrt{n}}}\right)}\right)
\end{align*}
Further, the resulting algorithm makes $O\big(\min\big\{\frac{\sqrt{\kappa}n^2\epsilon^{1.5}}{\log^2(n)\sqrt{d\log(1/\delta)\tilde{\kappa}}}, \frac{\sqrt{\kappa}n^{3/2}}{\log^{3/2}(n)}\big\}\big)$ gradient evaluations.

\label{thm:vi-generalized-rr-convergence}
Let $\lambda \geq \frac{48\tilde{L}\kappa^2}{B\sqrt{n'}}$
and $\mathcal{A}_{\mathsf{sub}}$ be such that for all $t\in [T]$ it holds that                            $\underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z^*_{S,t}\right\|^2 \right] \leq \frac{B^2}{12\cdot2^{2t}\kappa^2}$.
Then Recursive Regularization satisfies
\begin{align*}
    \operatorname{VI-Gap}(\mathcal{R}_{\text{VI}}) = O\Big(\log(n)B^2\lambda\Big).
\end{align*}

\label{fact:rel-acc-bounds-distance-vi}
Let $G:\ensuremath{\mathcal{Z}}\mapsto\mathbb{R}^d$ be a $\mu$-strongly monotone operator and let $z^*$ be the equilibrium point. Then 
$\|z-z^*\|^2 \leq \frac{2\left\langle G(z),z-z^* \right\rangle}{\mu}$.

\label{lem:phase-distance-bound-vi}
Assume the conditions of Theorem \ref{thm:vi-generalized-rr-convergence} hold. Then for every $t\in[T]$, the following holds
\begin{enumerate}[label=\textbf{P.\arabic*}]
    \item $\underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z_{t}^*\right\| \right]^2 \leq \underset{}{\mathbb{E}}\left[ \left\|\bar{z}_t - z_{t}^*\right\|^2 \right] \leq \frac{B^2}{2^{2t}\kappa^2}$; and, \label{prop:p1-vi}
    \item $B_t^2 := \underset{}{\mathbb{E}}\left[ \left\|z_{t}^* - z^*_{t-1}\right\| \right]^2 \leq \underset{}{\mathbb{E}}\left[ \left\|z_{t}^* - z^*_{t-1}]\right\|^2 \right] \leq \frac{B^2}{2^{2(t-1)}}$. \label{prop:p2-vi}
\end{enumerate}

(Implicit in \cite[Theorem 3]{PB16}) \label{lem:accel-alg-guarantee}
Let $\beta,\mu,K>0$ and $c$ a universal constant. Let $g:\ensuremath{\mathcal{Z}}\times\ensuremath{\mathcal{X}}\mapsto\mathbb{R}$ be monotone and $\beta$-Lipschitz 
and $\rho:\ensuremath{\mathcal{Z}}\mapsto\mathbb{R}$ a $\mu$-strongly monotone operator. Let $z_S^*$ be the equilibrium of $G_S(z) = \frac{1}{n}\sum_{x\in S} g(z;x) + \rho(z)$. There exists an algorithm, which in $O(n+\sqrt{n}K\frac{\beta}{\mu})$ gradient evaluations find a point $\bar{z}$ such that $\underset{}{\mathbb{E}}\left[ \|z^*-\bar{z}\|_2 \right] = c B e^{-K}$.

\label{thm:l2-minimax-alg}
Let $\mathcal{A}_{\mathsf{sub}}$ be as described above. Then Algorithm \ref{alg:recursive-regularization} is $(\epsilon,\delta)$-DP and when run with $\lambda = \frac{48}{B}\left({\frac{L}{\sqrt{n'}} + \frac{L\sqrt{d\log(2/\delta)}}{n'\epsilon}}\right)$ satisfies
\begin{align*}
    \operatorname{Gap}(\mathcal{R}_{\text{SVI}}) = O\left({\frac{\log^{3/2}(n)BL}{\sqrt{n}} + \frac{\log^2(n)BL\sqrt{d\log(1/\delta)}}{n\epsilon}}\right),
\end{align*}
and runs in at most $O(n + \beta n\log(n/\delta))$ gradient evaluations.

(\cite[Theorem 7.1]{bassily2021non})
Let $p\in(1,2)$ and $p^*=\frac{p}{p-1}$ and $\ensuremath{\mathcal{Z}}=\mathcal{B}_{\|\cdot\|_p}(1)$. Let $\epsilon>0$ and $0 < \delta < \frac{1}{n^{1+\Omega(1)}}$ and let $f(z;x)=\left\langle z,x \right\rangle$. For any $(\epsilon,\delta)$-DP algorithm $\mathcal{A}$, there exists a distribution $\mathcal{D}$ over $\ensuremath{\mathcal{X}}=\mathcal{B}_{\|\cdot\|_{p^*}}(1)$ such that 
\begin{align*}
    \underset{S\sim\mathcal{D}^n,\mathcal{A}}{\mathbb{E}}\left[ F{\mathcal{D}}(\mathcal{A}(S) - \min_{z\in\ensuremath{\mathcal{Z}}}\left\{{F_{\mathcal{D}}(z)}\right\} \right] = \tilde{\Omega}\left({\max\left\{{\frac{1}{\sqrt{n}}, \frac{(p-1)\sqrt{d}}{n\epsilon}}\right\}}\right).
\end{align*}
